using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Experimental.Rendering;
internal class CommandScript : IRunCommand {
 public void Execute(ExecutionResult result) {
 const int w=65,h=65;
 var shader=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<ComputeShader>("Packages/com.vivid.render-pipelines/Shaders/Core/Private/CSMShadowResolve.compute"));
 var src=new Texture2D(w,h,TextureFormat.RFloat,false,true);var device=new Texture2D(w,h,TextureFormat.RFloat,false,true);var normal=new Texture2D(w,h,TextureFormat.RGBAFloat,false,true);
 var horizontal=Make(w,h,GraphicsFormat.R16_SFloat);var spatial=Make(w,h,GraphicsFormat.R16_SFloat);var temporal=Make(w,h,GraphicsFormat.R16_SFloat);
 var signal=new[]{Make(w,h,GraphicsFormat.R16G16B16A16_SFloat),Make(w,h,GraphicsFormat.R16G16B16A16_SFloat)};var depth=new[]{Make(w,h,GraphicsFormat.R32_SFloat),Make(w,h,GraphicsFormat.R32_SFloat)};
 var cmd=new CommandBuffer();string report="";
 try {var devices=new float[w*h];var normals=new Color[w*h];for(int i=0;i<w*h;i++){devices[i]=.5f;normals[i]=new Color(.5f,.5f,0,0);}device.SetPixelData(devices,0);device.Apply();normal.SetPixels(normals);normal.Apply();
 for(int test=0;test<4;test++) {
  int axis=test/2,speed=test%2==0?1:4;float maxError=0;double maxLag=0;float tailError=0;
  for(int frame=0;frame<24;frame++) {
   int edge=8+speed*Math.Max(0,frame-4);var values=new float[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)values[y*w+x]=(axis==0?x:y)>=edge?1:0;src.SetPixelData(values,0);src.Apply();
   cmd.Clear();cmd.SetComputeIntParam(shader,"_CSMOutputWidth",w);cmd.SetComputeIntParam(shader,"_CSMOutputHeight",h);cmd.SetComputeVectorParam(shader,"_ZBufferParams",new Vector4(0,0,2,1));cmd.SetComputeVectorParam(shader,"_VSMHistoryParameters",new Vector4(frame>0?1:0,1,4,0));cmd.SetComputeMatrixParam(shader,"_CSMInvViewProjMatrix",Matrix4x4.identity);cmd.SetComputeMatrixParam(shader,"_VSMPreviousViewProjection",Matrix4x4.identity);cmd.SetComputeMatrixParam(shader,"_VSMPreviousView",Matrix4x4.Translate(new Vector3(0,0,-1)));cmd.SetComputeMatrixParam(shader,"_VSMCurrentView",Matrix4x4.Translate(new Vector3(0,0,-1)));
   foreach(string name in new[]{"VSMShadowBilateralFilterH","VSMShadowBilateralFilterV","VSMShadowTemporalV"}){
    int k=shader.FindKernel(name);bool first=name.EndsWith("H"),last=name=="VSMShadowTemporalV";cmd.SetComputeTextureParam(shader,k,"_DepthTexture",device);cmd.SetComputeTextureParam(shader,k,"_GBuffer1",normal);cmd.SetComputeTextureParam(shader,k,"_CSMShadowFilterSource",first?(Texture)src:horizontal);cmd.SetComputeTextureParam(shader,k,"_CSMShadowFilterTexture",first?horizontal:last?temporal:spatial);
    if(last){cmd.SetComputeTextureParam(shader,k,"_VSMHistoryPrevious",signal[1-frame%2]);cmd.SetComputeTextureParam(shader,k,"_VSMDepthPrevious",depth[1-frame%2]);cmd.SetComputeTextureParam(shader,k,"_VSMHistoryCurrent",signal[frame%2]);cmd.SetComputeTextureParam(shader,k,"_VSMDepthCurrent",depth[frame%2]);}
    cmd.DispatchCompute(shader,k,(w+7)/8,(h+7)/8,1);
   }
   Graphics.ExecuteCommandBuffer(cmd);var ra=AsyncGPUReadback.Request(spatial,0,TextureFormat.RFloat);var rb=AsyncGPUReadback.Request(temporal,0,TextureFormat.RFloat);ra.WaitForCompletion();rb.WaitForCompletion();if(ra.hasError||rb.hasError)throw new Exception("readback");var a=ra.GetData<float>();var b=rb.GetData<float>();double lag=0;
   for(int i=0;i<w;i++){int p=axis==0?w*(h/2)+i:i*w+w/2;float e=Math.Abs(a[p]-b[p]);maxError=Math.Max(maxError,e);lag+=a[p]-b[p];if(Math.Abs(i-edge)>5)tailError=Math.Max(tailError,e);}maxLag=Math.Max(maxLag,Math.Abs(lag));
  }
  if(maxLag>1||tailError>.001)throw new Exception("case="+test+" lag="+maxLag+" tail="+tailError);
  report+="axis="+axis+" speed="+speed+" frames=24 maxPixelDifference="+maxError+" maxEquivalentLagPixels="+maxLag+" beyondFilterSupport="+tailError+"\n";
 }
 File.WriteAllText("Packages/VividRP/Temp~/vsm-temporal/motion-gpu.txt",report+"passed=4");result.Log(report+"passed=4");
 }finally{cmd.Dispose();foreach(var o in new UnityEngine.Object[]{shader,src,device,normal,horizontal,spatial,temporal,signal[0],signal[1],depth[0],depth[1]})UnityEngine.Object.DestroyImmediate(o);}
 }
 static RenderTexture Make(int w,int h,GraphicsFormat format){var r=new RenderTexture(new RenderTextureDescriptor(w,h,format,0){enableRandomWrite=true});r.Create();return r;}
}
